function priceComparison(product){
 const block=el('div',undefined,'price-comparison');
 const local=el('div',undefined,'reference-price');local.append(el('p',t('Australian reference price','澳洲参考价'),'price-label'),el('p',product.price||t('Quote required','需询价'),'comparison-amount'),el('small',product.price?t('Listed by Advantage Industries','Advantage Industries 公开价格'):t('No public price verified','未核实公开价格')));
 const ours=el('div',undefined,'our-price');const offer=ourOffers[product.id];
 ours.append(el('p',t('Our price','我们的价格'),'price-label'),el('p',offer?new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(offer.amount):t('Quote pending','待确认报价'),'comparison-amount'),el('small',offer?t(...offer.scope):t('Selling price not set yet','售价尚未设定')));
 block.append(local,ours);
 // A supplier listing alone is not evidence of an equivalent, delivered comparison.
 const note=el('p',t('Savings pending a matching specification and cost breakdown.','节省金额须在规格及费用范围一致后计算。'),'comparison-note');block.append(note);return block;
}
